{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      { "@type": "Question", "name": "Can monday.com import subitems natively?", "acceptedAnswer": { "@type": "Answer", "text": "No. Monday.com's native CSV import only creates top-level items. It has no built-in way to create subitems from a file. Monday.com Inspector is a free Chrome extension that solves this limitation." } },
      { "@type": "Question", "name": "What CSV format do I need to import subitems into monday.com?", "acceptedAnswer": { "@type": "Answer", "text": "Your CSV needs at least a column for the parent item name (or ID) and a column for the subitem name. You can also include any other subitem columns: status, assignee, date, timeline, etc." } },
      { "@type": "Question", "name": "Can I import parent items and subitems at the same time?", "acceptedAnswer": { "@type": "Answer", "text": "Yes. Monday.com Inspector supports full two-phase import: it first creates parent items (with their column values), then creates subitems underneath them." } },
      { "@type": "Question", "name": "Does monday.com Inspector work with monday.com board exports?", "acceptedAnswer": { "@type": "Answer", "text": "Yes. Upload a monday.com XLSX board export and the tool auto-detects the format, preserving groups, parent items, and subitems. You can migrate a board between workspaces in minutes." } },
      { "@type": "Question", "name": "Is there a row limit for importing subitems?", "acceptedAnswer": { "@type": "Answer", "text": "No. Monday.com Inspector has no row limits. You can import thousands of subitems in a single operation. The tool handles batching and rate limits automatically." } }
    ]
  }

{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      { "@type": "Question", "name": "What CSV format does monday.com accept?", "acceptedAnswer": { "@type": "Answer", "text": "Monday.com accepts CSV files with a header row in the first row. Columns should be separated by commas. The file must use UTF-8 encoding. Column names should match your board's column titles for automatic mapping." } },
      { "@type": "Question", "name": "Is there a row limit for monday.com CSV import?", "acceptedAnswer": { "@type": "Answer", "text": "Monday.com's native import has an undocumented row limit, and large files may time out or fail. Monday.com Inspector has no row limit — it batches and rate-limits automatically, handling thousands of rows reliably." } },
      { "@type": "Question", "name": "Can I import multiple column types from CSV into monday.com?", "acceptedAnswer": { "@type": "Answer", "text": "Monday.com's native import supports a limited set of column types. Monday.com Inspector supports all major column types including Status, People, Date, Timeline, Dropdown, Checkbox, Link, Phone, Email, Rating, and Numbers." } },
      { "@type": "Question", "name": "Can I import subitems from a CSV into monday.com?", "acceptedAnswer": { "@type": "Answer", "text": "No, monday.com's native CSV import does not support subitems. Use Monday.com Inspector to import subitems from CSV — it creates parent items and their subitems in a single import operation." } },
      { "@type": "Question", "name": "Can I import a monday.com board export back into monday.com?", "acceptedAnswer": { "@type": "Answer", "text": "Yes. Monday.com Inspector can re-import a monday.com XLSX board export, preserving groups, parent items, and subitems. This makes it easy to copy or migrate boards between workspaces." } },
      { "@type": "Question", "name": "What is the best way to format dates in a monday.com CSV import?", "acceptedAnswer": { "@type": "Answer", "text": "Use ISO 8601 date format: YYYY-MM-DD (e.g., 2026-04-15). For timeline columns, use two date columns: start date and end date, both in YYYY-MM-DD format." } }
    ]
  }

{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      { "@type": "Question", "name": "Can monday.com bulk update items natively?", "acceptedAnswer": { "@type": "Answer", "text": "Monday.com has a limited bulk action feature in the board view that lets you select multiple items and change a single column at a time. It doesn't support updating from a file, updating multiple columns at once, or updating subitems. Monday.com Inspector fills this gap." } },
      { "@type": "Question", "name": "What columns can I bulk update in monday.com?", "acceptedAnswer": { "@type": "Answer", "text": "Monday.com Inspector supports bulk updating Status, People, Date, Timeline, Dropdown, Checkbox, Text, Numbers, Link, Phone, Email, and Rating columns — for both parent items and subitems." } },
      { "@type": "Question", "name": "Can I bulk update subitems in monday.com?", "acceptedAnswer": { "@type": "Answer", "text": "Yes. Monday.com Inspector supports bulk updating subitems. Include the subitem ID column in your CSV update file and enable subitem mode. You can update any subitem column type." } },
      { "@type": "Question", "name": "How do I find item IDs in monday.com for bulk update?", "acceptedAnswer": { "@type": "Answer", "text": "You can find item IDs by exporting your board (Board menu → Export → Excel). The export includes item IDs in a column. You can also use Monday.com Inspector's Schema tab to query item IDs via the GraphQL engine." } },
      { "@type": "Question", "name": "Is there a limit to how many items I can bulk update?", "acceptedAnswer": { "@type": "Answer", "text": "Monday.com Inspector has no row limit for bulk updates. It handles batching and monday.com API rate limits automatically, so you can safely update thousands of items." } }
    ]
  }

{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      { "@type": "Question", "name": "Do I need to be a developer to use monday.com's GraphQL API?", "acceptedAnswer": { "@type": "Answer", "text": "No. With the Query Inspector you pick a template, plug in your board ID, and run. No code, no setup. The 14 starter templates cover boards, items, subitems, users, workspaces, and audit queries. You can save your own customised queries to a local library." } },
      { "@type": "Question", "name": "How do I get a monday.com API token?", "acceptedAnswer": { "@type": "Answer", "text": "In monday.com, click your avatar (top right) → Admin → API. Generate a personal API v2 token and copy it. Paste it into Monday.com Inspector's first-run setup card. The token is stored in chrome.storage.local and is only ever sent to https://api.monday.com/v2." } },
      { "@type": "Question", "name": "What's the difference between API version 2024-10 and 2026-04?", "acceptedAnswer": { "@type": "Answer", "text": "API 2026-04 unlocks multi-level boards — up to 5 nested levels on the same board, with rolled-up parent values. The hierarchy_types argument and the BatteryValue rollup column type are 2026-04+ features. Monday.com Inspector ships with API-Version 2026-04 and falls back gracefully on tenants on older versions." } },
      { "@type": "Question", "name": "Can I run mutations from the Query Inspector?", "acceptedAnswer": { "@type": "Answer", "text": "Yes. The Query Inspector executes any valid monday.com GraphQL operation — queries and mutations both. The complexity meter shows you the cost before each run so you don't blow your account's budget." } },
      { "@type": "Question", "name": "How does the complexity budget work?", "acceptedAnswer": { "@type": "Answer", "text": "Monday.com gives every account a complexity budget that resets per minute. Each query consumes points based on the number of fields and items it touches. The Query Inspector shows your remaining budget in a pill next to every run, and templates are tagged 'heavy' when they're known to be expensive." } }
    ]
  }
